def is_palindrome(string: str) -> bool:     """ Test if given string is a palindrome """     return string == string[::-1]   def make_palindrome(string: str) -> str:     """ Find the shortest palindrome that begins with a supplied string.     Algorithm idea is simple:     - Find the longest postfix of supplied string that is a palindrome.     - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.     >>> make_palindrome('')     ''     >>> make_palindrome('cat')     'catac'     >>> make_palindrome('cata')     'catac'     """     longest_palindrome = ""
     for i in range(len(string)-1, -1, -1):
         for j in range(i+1, len(string)):
             if string[i:j+1] == string[j+1::-1]:
                 if len(string[i:j+1]) > len(longest_palindrome):
                     longest_palindrome = string[i:j+1]
     return string + string[len(longest_palindrome):][::-1]
